const packetNames={1:'Test payload',2:'ACK',3:'Transfer metadata',4:'Data chunk',5:'Transfer finish',6:'Band change',7:'Return to control',8:'Control / completion'};
let rxRun=null;
function startRxRun(session){rxRun={session,start:performance.now(),last:performance.now(),ended:null,bytes:0,packets:0,state:'receiving',rawBitrate:2000/(+$('speed').value)};diagLog('RX_RUN_START',{sessionId:session});renderRxRun();}
