 $('diagLog').textContent=diagEvents.slice(-80).map(e=>`${e.at.slice(11,23)} ${e.event} ${JSON.stringify(Object.fromEntries(Object.entries(e).filter(([k])=>!['at','session','event'].includes(k))))}`).join('\n')||'No events yet. Start receiving, then start the sender.';
