function config(){const low=+$('low').value,high=+$('high').value,ms=+$('speed').value,gain=+$('gain').value/100;if(!Number.isFinite(low)||!Number.isFinite(high)||low<18000||high>23000||high-low<750)throw Error('Choose a band at least 750 Hz wide, within 18,000–23,000 Hz');if(low<20000&&!$('audible').checked)throw Error('Frequencies below 20 kHz may be audible. Enable them in Advanced settings first.');if(ctx&&high>ctx.sampleRate/2-200)throw Error(`This device supports up to ${Math.floor(ctx.sampleRate/2-200)} Hz for this test. Lower the upper frequency.`);return {low,high,ms,gain};}
