function renderHistory(){const body=$('history');body.replaceChildren();$('count').textContent=history.length;if(!history.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=6;td.className='empty';td.textContent='No saved results yet. Record a signal or run a test.';tr.append(td);body.append(tr);return;}for(const r of [...history].reverse()){const tr=document.createElement('tr');const values=[`${new Date(r.at).toLocaleString('en-US',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})} / ${r.device||'—'}`,`${r.direction||'—'} / ${r.distanceCm??'—'} cm`,r.kind||'—',(r.range||[]).map(v=>(v/1000).toFixed(2)).join('–')+' kHz',`${Math.round((r.gain||0)*100)}% / ${r.systemVolume||'—'}`,r.kind==='frequency-scan'?`${r.bands?.filter(b=>b.measurements?.length).length||0} measured bands · ${r.rawBitrate} bit/s raw`:r.kind==='spectrum'?(r.recommended?`${(r.recommended[0]/1000).toFixed(2)}–${(r.recommended[1]/1000).toFixed(2)} kHz suggested`:'No continuous band found'): `${Number(r.goodputBps||0).toFixed(1)} bit/s · ${r.success||0}/${r.attempted||0} ACK`];for(const v of values){const td=document.createElement('td');td.textContent=v;tr.append(td);}body.append(tr);}}
