function setListen(on){listening=on;receiver?.port.postMessage({muted:!on||tx});$('listen').textContent=on?'✓ Listening / sending ACKs':'Listen / send ACKs';}
function lock(on){busy=on;for(const id of ['low','high','speed','gain','volume','role','direction','distance','device','audible','capture','sweep','bench','sendText','file','listen','useBand','scanStart','scanRange','scanWidth','scanStep','scanRepeats','scanSpeed','scanShowLatest','quickRx','quickTx','quickStart'])$(id).disabled=on||id==='useBand'&&!recommendation;syncQuickButtons();}
